 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The three-color pattern on the top edge identifies the columns to project.
    motif_cols = {grid[0][c]: c for c in range(w) if grid[0][c] != 0}
    stop_rows = {}
    markers = []
    for r in range(1, h):
        for c in (0, w - 1):
            color = grid[r][c]
            if color in motif_cols:
                markers.append((r, c, color))
                stop_rows[color] = r
    # Project each motif color down until the matching edge marker, or to bottom.
    for color, c in motif_cols.items():
        end = stop_rows.get(color, h - 1)
        for r in range(end + 1):
            out[r][c] = color
    # Extend matching left/right edge markers inward to the motif's column.
    for r, edge, color in markers:
        target = motif_cols[color]
        lo, hi = sorted((edge, target))
        for c in range(lo, hi + 1):
            out[r][c] = color
    return out
